// course 1: solid 8x8 dark grey
fill(-4,-4,8,8,72,{kit:"bricks"});
// course 2: 8x8 again but with notched corners for rough look
fill(-4,-4,8,8,72,{kit:"bricks",bond:1,skip:[[-4,-4,1,1],[3,-4,1,1],[-4,3,1,1],[3,3,1,1]]});
// course 3: 6x6 stepped in, dark grey
fill(-3,-3,6,6,0,{kit:"bricks"});
log("base parts: "+count());

// lower tower: 6x6 hollow ring, 6 courses, bands of 2
for(let c=0;c<6;c++){
  const col = (Math.floor(c/2)%2===0)?4:15;
  ring(-3,-3,6,6,1,col,{bond:c%2});
}
// transition: plate ledge 6x6 ring top? go straight to 4x4 upper
for(let c=0;c<8;c++){
  const col = (Math.floor(c/2)%2===0)?15:4;
  ring(-2,-2,4,4,1,col,{bond:c%2});
}
log("parts "+count());

const cols=[15,15,4,4,15,15];
for(let c=0;c<6;c++){ ring(-2,-2,4,4,1,cols[c],{bond:c%2}); }
log("parts "+count());

// railing: 1x1 round plates around the 6x6 gallery deck perimeter
for(let x=-3;x<=2;x++){ put('6141',0,x,-3); put('6141',0,x,2); }
for(let z=-2;z<=1;z++){ put('6141',0,-3,z); put('6141',0,2,z); }
log("parts "+count());
